import { Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import { Object3D } from 'three';

export default function createNode(config, ctx) {
  // Load texture (cached by ctx)
  const imageUrl = config.assets?.imageUrl;
  const texture = imageUrl ? ctx.textureLoader(imageUrl) : null;

  // Geometry – unit plane; texture aspect handled by scaling later if needed
  const geometry = new PlaneGeometry(1, 1);

  // Material – basic node material with texture map
  const material = new MeshBasicNodeMaterial({
    map: texture,
  });

  const mesh = new Mesh(geometry, material);

  // Helper to apply vec3 from array or object
  const applyVec3 = (target, value) => {
    if (Array.isArray(value) && value.length === 3) {
      target.set(value[0], value[1], value[2]);
    } else if (value && typeof value === 'object') {
      target.set(value.x ?? 0, value.y ?? 0, value.z ?? 0);
    }
  };

  // Position / rotation / scale from config (fallback to defaults)
  const position = config.position ?? config.scenePlacement?.position ?? [0, 0, 0];
  const rotation = config.rotation ?? config.scenePlacement?.rotation ?? [0, 0, 0];
  const scale = config.scale ?? config.scenePlacement?.scale ?? [1, 1, 1];

  applyVec3(mesh.position, position);
  applyVec3(mesh.rotation, rotation);
  applyVec3(mesh.scale, scale);

  // No cinematic primitives to apply for this node
  // (placeholder for future primitives)

  // Event handlers container (empty for this static node)
  mesh.userData.handlers = {};

  // Keep track of any GSAP timelines (none in this static node, but pattern kept)
  const _timelines = [];

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
    _timelines.forEach((t) => t.kill());
  };

  return mesh;
}
